sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading) {
        return;
    }

    calculateEligibility();

    function calculateEligibility() {

        var branches = g_form.getValue('eligible_branches');
        var cgpa = g_form.getValue('minimum_cgpa');
        var backlogs = g_form.getValue('max_backlogs');
        var skills = g_form.getValue('mandatory_skills');

        // Wait until all four criteria are filled
        if (!branches || !cgpa || !backlogs || !skills) {
            g_form.setValue('eligibility_count', '0');
            return;
        }

        var ga = new GlideAjax('PlacementDriveEligibility');

        ga.addParam('sysparm_name', 'calculateEligibility');
        ga.addParam('sysparm_branches', branches);
        ga.addParam('sysparm_cgpa', cgpa);
        ga.addParam('sysparm_backlogs', backlogs);
        ga.addParam('sysparm_skills', skills);

        ga.getXMLAnswer(function(answer) {

            if (answer) {
                g_form.setValue('eligibility_count', answer);
            } else {
                g_form.setValue('eligibility_count', '0');
            }

        });
    }
}
